import { supabase } from './client'

/**
 * Compatibility wrapper kept for src/features/admin/MembersPage.tsx.
 * Backed by tenant_memberships joined to central_users (docs/schema-map.md).
 *
 * NOTE: the `members` table referenced by the previous implementation does NOT exist
 * in the schema. This file preserves the same exported API so the admin page works.
 */
export type Member = {
  id: string
  tenantId: string
  userId: string
  name: string
  email: string
  role: 'owner' | 'admin' | 'member' | 'viewer'
  status: 'active' | 'pending' | 'suspended'
  joinedAt: string
}

type Row = {
  id: string
  tenant_id: string
  user_id: string
  role: string
  status: string
  joined_at: string | null
  central_user: { email: string | null } | null
}

function mapRole(r: string): Member['role'] {
  if (r === 'owner' || r === 'admin' || r === 'viewer') return r
  return 'member'
}
function mapStatus(s: string): Member['status'] {
  if (s === 'pending' || s === 'suspended') return s
  return 'active'
}

export const membersService = {
  async listMembers(tenantId: string): Promise<Member[]> {
    // central_users.id == tenant_memberships.user_id by app convention (= auth.uid()).
    // PostgREST embedded select uses the FK; we don't have an FK from tenant_memberships
    // to central_users, so do two queries and stitch in JS.
    const { data: rows, error } = await supabase
      .from('tenant_memberships')
      .select('id, tenant_id, user_id, role, status, joined_at')
      .eq('tenant_id', tenantId)
      .order('joined_at', { ascending: false })
    if (error) throw error
    const ids = (rows ?? []).map((r) => r.user_id)
    let emails: Record<string, string | null> = {}
    if (ids.length) {
      const { data: users } = await supabase
        .from('central_users')
        .select('id, email')
        .in('id', ids)
      emails = Object.fromEntries((users ?? []).map((u) => [u.id as string, (u.email as string | null) ?? null]))
    }
    return (rows ?? []).map((r: Row | unknown) => {
      const row = r as Row
      const email = emails[row.user_id] ?? ''
      return {
        id: row.id,
        tenantId: row.tenant_id,
        userId: row.user_id,
        name: email ? email.split('@')[0] : row.user_id.slice(0, 8),
        email,
        role: mapRole(row.role),
        status: mapStatus(row.status),
        joinedAt: row.joined_at ?? '',
      }
    })
  },

  /**
   * Invite by email. Without a central_users row we cannot create a tenant_memberships
   * row (we lack a user_id). For now, write the invitation into `invitations` so the
   * admin flow is not blocked; bootstrap will pick it up on first sign-in (future work).
   */
  async inviteMember(tenantId: string, email: string, role: Member['role']): Promise<void> {
    const { error } = await supabase
      .from('invitations')
      .insert({ tenant_id: tenantId, invitee_email: email, role, status: 'pending' })
    if (error) throw error
  },
}
